//! Text disassembler producing the same format as Microsoft's d3dcompiler `D3DDisassemble` (the "Generated by Microsoft (R) D3D Shader
//! Disassembler" listing): signature comment tables, then the declarations and instructions.

use crate::container::{Container, Rdef, Result, SigElement, Signature};
use crate::decode::decode_program;
use crate::ir::*;
use crate::opcode::Opcode;
use std::fmt::Write;

/// How immediates of an operand are printed.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Ty {
    Float,
    Int,
    Uint,
    /// bit operations: hex when the pattern looks like a float, decimal otherwise
    Bits,
    /// mov-like: zero/denormal/NaN patterns as decimal integers, normal floats as `%f`
    Untyped,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct DisasmOptions {
    /// `D3D_DISASM_PRINT_HEX_LITERALS`: float immediates are printed as exact bit patterns (`0x3f800000`)
    pub hex_literals: bool,
}

/// Numeric class of operand `i` (source index counted over all operands, destinations first) of `inst`.
pub fn operand_ty(inst: &Instruction, i: usize) -> Ty {
    use Opcode::*;
    let (nd, _) = inst.op.arity();
    let is_src = i >= nd;
    let s = i.saturating_sub(nd);
    match inst.op {
        Add | Mul | Mad | Div | Dp2 | Dp3 | Dp4 | Exp | Log | Frc | Rsq | Sqrt | Rcp | RoundNe | RoundNi | RoundPi | RoundZ | Eq | Lt | Ge | Ne | Ftoi | Ftou | Sincos | Min | Max
        | DerivRtx | DerivRty | DerivRtxCoarse | DerivRtxFine | DerivRtyCoarse | DerivRtyFine | F32toF16 | EvalCentroid => Ty::Float,
        Sample | SampleB | SampleL | SampleD | SampleC | SampleCLz | Lod | Gather4 | Gather4C | Gather4Po | Gather4PoC => {
            // dst, coord, resource, sampler, [extra float args]
            if !is_src { Ty::Float } else { match s { 0 => Ty::Float, 1 | 2 => Ty::Untyped, _ => Ty::Float } }
        }
        Iadd | Imul | Imad | Imax | Imin | Ineg | Ishl | Ishr | Ieq | Ige | Ilt | Ine | Itof | Ld | LdMs | Resinfo | Bufinfo => Ty::Int,
        Udiv | Umul | Umad | Umax | Umin | Ult | Uge | Ushr | Utof | Ubfe | Ibfe | Bfi | Countbits | FirstbitHi | FirstbitLo | FirstbitShi | Bfrev | Uaddc | Usubb | F16toF32 | LdRaw | LdStructured | StoreRaw | StoreStructured => Ty::Uint,
        And | Or | Xor | Not => Ty::Bits,
        _ => Ty::Untyped,
    }
}

pub fn fmt_float(x: f32) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() && x.to_bits() & 0x7fffff == 0x400000 { "-1.#IND00".into() } else if x.is_sign_negative() { "-1.#QNAN0".into() } else { "1.#QNAN0".into() };
    }
    if x.is_infinite() { return if x < 0.0 { "-1.#INF00".into() } else { "1.#INF00".into() }; }
    format!("{:.6}", x as f64)
}

fn looks_float(bits: u32) -> bool {
    let e = (bits >> 23) & 0xff;
    (1..=254).contains(&e)
}

pub fn fmt_imm(bits: u32, ty: Ty, o: &DisasmOptions) -> String {
    match ty {
        Ty::Float => if o.hex_literals { format!("0x{bits:08x}") } else { fmt_float(f32::from_bits(bits)) },
        Ty::Int => format!("{}", bits as i32),
        Ty::Uint => format!("{bits}"),
        Ty::Bits => if looks_float(bits) { format!("0x{bits:x}") } else { format!("{}", bits as i32) },
        Ty::Untyped => {
            if o.hex_literals { format!("0x{bits:08x}") }
            else if bits == 0 { "0".into() }
            else if bits == 0x8000_0000 || looks_float(bits) { if o.hex_literals { format!("0x{bits:08x}") } else { fmt_float(f32::from_bits(bits)) } }
            else { format!("{}", bits as i32) }
        }
    }
}

const COMP: [char; 4] = ['x', 'y', 'z', 'w'];

fn reg_prefix(ty: u8) -> &'static str {
    match ty {
        OperandType::TEMP => "r",
        OperandType::INPUT => "v",
        OperandType::OUTPUT => "o",
        OperandType::INDEXABLE_TEMP => "x",
        OperandType::SAMPLER => "s",
        OperandType::RESOURCE => "t",
        OperandType::CONSTANT_BUFFER => "cb",
        OperandType::IMMEDIATE_CONSTANT_BUFFER => "icb",
        OperandType::LABEL => "l",
        OperandType::STREAM => "m",
        OperandType::FUNCTION_BODY => "fb",
        OperandType::FUNCTION_TABLE => "ft",
        OperandType::INTERFACE => "fp",
        OperandType::INPUT_CONTROL_POINT => "vicp",
        OperandType::OUTPUT_CONTROL_POINT => "vocp",
        OperandType::INPUT_PATCH_CONSTANT => "vpc",
        OperandType::UAV => "u",
        OperandType::THREAD_GROUP_SHARED_MEMORY => "g",
        _ => "",
    }
}
pub fn special_name(ty: u8) -> Option<&'static str> {
    Some(match ty {
        OperandType::INPUT_PRIMITIVE_ID => "vPrim",
        OperandType::OUTPUT_DEPTH => "oDepth",
        OperandType::NULL => "null",
        OperandType::RASTERIZER => "rasterizer",
        OperandType::OUTPUT_COVERAGE_MASK => "oMask",
        OperandType::OUTPUT_CONTROL_POINT_ID => "vOutputControlPointID",
        OperandType::INPUT_FORK_INSTANCE_ID => "vForkInstanceID",
        OperandType::INPUT_JOIN_INSTANCE_ID => "vJoinInstanceID",
        OperandType::INPUT_DOMAIN_POINT => "vDomain",
        OperandType::THIS_POINTER => "this",
        OperandType::INPUT_THREAD_ID => "vThreadID",
        OperandType::INPUT_THREAD_GROUP_ID => "vThreadGroupID",
        OperandType::INPUT_THREAD_ID_IN_GROUP => "vThreadIDInGroup",
        OperandType::INPUT_COVERAGE_MASK => "vCoverage",
        OperandType::INPUT_THREAD_ID_IN_GROUP_FLATTENED => "vThreadIDInGroupFlattened",
        OperandType::INPUT_GS_INSTANCE_ID => "vGSInstanceID",
        OperandType::OUTPUT_DEPTH_GE => "oDepthGE",
        OperandType::OUTPUT_DEPTH_LE => "oDepthLE",
        OperandType::CYCLE_COUNTER => "vCycleCounter",
        OperandType::OUTPUT_STENCIL_REF => "oStencilRef",
        OperandType::INNER_COVERAGE => "vInnerCoverage",
        _ => return None,
    })
}

fn fmt_index(i: &Index, o: &DisasmOptions) -> String {
    match &i.rel {
        None => format!("{}", i.imm),
        Some(r) => {
            let rs = fmt_operand(r, Ty::Untyped, o, false);
            format!("{rs} + {}", i.imm)
        }
    }
}

pub fn fmt_operand(op: &Operand, ty: Ty, o: &DisasmOptions, upper_cb: bool) -> String {
    let mut s = String::new();
    let t = op.ty.0;
    if t == OperandType::IMMEDIATE32 {
        let sep = if ty == Ty::Untyped { "," } else { ", " };
        let vals: Vec<String> = op.imm.iter().map(|&b| fmt_imm(b, ty, o)).collect();
        s = format!("l({})", vals.join(sep));
    } else if t == OperandType::IMMEDIATE64 {
        let v: Vec<String> = op.imm.chunks(2).map(|c| { let b = (c[0] as u64) | ((c[1] as u64) << 32); format!("d({:.6})", f64::from_bits(b)) }).collect();
        s = format!("l({})", v.join(", "));
    } else if let Some(n) = special_name(t) {
        s.push_str(n);
    } else {
        let prefix = if t == OperandType::CONSTANT_BUFFER && upper_cb { "CB" } else { reg_prefix(t) };
        s.push_str(prefix);
        let plain = |i: &Index| i.rel.is_none();
        match t {
            OperandType::CONSTANT_BUFFER => {
                if let Some(i0) = op.index.first() {
                    if plain(i0) { let _ = write!(s, "{}", i0.imm); } else { let _ = write!(s, "[{}]", fmt_index(i0, o)); }
                }
                for i in op.index.iter().skip(1) { let _ = write!(s, "[{}]", fmt_index(i, o)); }
            }
            OperandType::INDEXABLE_TEMP => {
                if let Some(i0) = op.index.first() { let _ = write!(s, "{}", i0.imm); }
                for i in op.index.iter().skip(1) { let _ = write!(s, "[{}]", fmt_index(i, o)); }
            }
            _ => {
                if op.index.len() == 1 && plain(&op.index[0]) {
                    let _ = write!(s, "{}", op.index[0].imm);
                } else {
                    for i in &op.index { let _ = write!(s, "[{}]", fmt_index(i, o)); }
                }
            }
        }
    }
    match if upper_cb || t == OperandType::IMMEDIATE32 || t == OperandType::IMMEDIATE64 { Sel::None } else { op.sel } {
        Sel::None => {}
        Sel::Mask(m) => {
            if t != OperandType::NULL {
                s.push('.');
                for (c, ch) in COMP.iter().enumerate() { if m & (1 << c) != 0 { s.push(*ch); } }
            }
        }
        Sel::Swizzle(sw) => {
            s.push('.');
            for c in sw { s.push(COMP[c as usize & 3]); }
        }
        Sel::Select1(c) => { s.push('.'); s.push(COMP[c as usize & 3]); }
    }
    match op.modifier {
        Modifier::None => s,
        Modifier::Neg => format!("-{s}"),
        Modifier::Abs => format!("|{s}|"),
        Modifier::AbsNeg => format!("-|{s}|"),
    }
}

pub fn dim_name(d: u8) -> &'static str {
    match d { 1 => "buffer", 2 => "texture1d", 3 => "texture2d", 4 => "texture2dms", 5 => "texture3d", 6 => "texturecube", 7 => "texture1darray", 8 => "texture2darray", 9 => "texture2dmsarray", 10 => "texturecubearray", 11 => "raw_buffer", 12 => "structured_buffer", _ => "unknown" }
}
pub fn ret_name(t: u8) -> &'static str {
    match t { 1 => "unorm", 2 => "snorm", 3 => "sint", 4 => "uint", 5 => "float", 6 => "mixed", 7 => "double", 8 => "continued", 9 => "unused", _ => "?" }
}
fn ret_list(r: [u8; 4]) -> String { format!("({},{},{},{})", ret_name(r[0]), ret_name(r[1]), ret_name(r[2]), ret_name(r[3])) }

pub fn sysvalue_long(v: u32) -> &'static str {
    match v {
        0 => "undefined", 1 => "position", 2 => "clip_distance", 3 => "cull_distance", 4 => "rendertarget_array_index", 5 => "viewport_array_index", 6 => "vertex_id", 7 => "primitive_id",
        8 => "instance_id", 9 => "is_front_face", 10 => "sample_index", 11 => "finalQuadUeq0EdgeTessFactor", 12 => "finalQuadVeq0EdgeTessFactor", 13 => "finalQuadUeq1EdgeTessFactor",
        14 => "finalQuadVeq1EdgeTessFactor", 15 => "finalQuadUInsideTessFactor", 16 => "finalQuadVInsideTessFactor", 17 => "finalTriUeq0EdgeTessFactor", 18 => "finalTriVeq0EdgeTessFactor",
        19 => "finalTriWeq0EdgeTessFactor", 20 => "finalTriInsideTessFactor", 21 => "finalLineDetailTessFactor", 22 => "finalLineDensityTessFactor", _ => "unknown",
    }
}
fn interp_name(m: u32) -> &'static str {
    match m { 0 => "undefined", 1 => "constant", 2 => "linear", 3 => "linear centroid", 4 => "linear noperspective", 5 => "linear noperspective centroid", 6 => "linear sample", 7 => "linear noperspective sample", _ => "?" }
}
fn global_flags(f: u32) -> String {
    let names = ["refactoringAllowed", "enableDoublePrecisionFloatOps", "forceEarlyDepthStencil", "enableRawAndStructuredBuffers", "skipOptimization", "enableMinimumPrecision", "enable11_1DoubleExtensions", "enable11_1ShaderExtensions"];
    let v: Vec<&str> = names.iter().enumerate().filter(|(i, _)| f & (1 << i) != 0).map(|(_, n)| *n).collect();
    v.join(", ")
}

fn test_suffix(inst: &Instruction) -> &'static str { if inst.test_nz() { "_nz" } else { "_z" } }

pub struct Disassembler<'a> {
    pub shader: &'a Shader,
    pub opts: DisasmOptions,
}

impl Disassembler<'_> {
    fn mnemonic(&self, inst: &Instruction) -> String {
        use Opcode::*;
        let mut n = inst.op.name().to_string();
        if inst.saturate() && !inst.op.is_decl() { n.push_str("_sat"); }
        match inst.op {
            If | Breakc | Continuec | Retc | Callc | Discard => n.push_str(test_suffix(inst)),
            Resinfo => match (inst.token >> 11) & 3 { 1 => n.push_str("_rcpFloat"), 2 => n.push_str("_uint"), _ => {} },
            Sync => {
                let f = (inst.token >> 11) & 0xf;
                if f & 4 != 0 { n.push_str("_uglobal"); }
                if f & 2 != 0 { n.push_str("_ugroup"); }
                if f & 1 != 0 { n.push_str("_g"); }
                if f & 8 != 0 { n.push_str("_t"); }
            }
            _ => {}
        }
        if inst.ext.offset.is_some() { n.push_str("_aoffimmi"); }
        if inst.ext.res_dim.is_some() { n.push_str("_indexable"); }
        if let Some(o) = inst.ext.offset { let _ = write!(n, "({},{},{})", o[0], o[1], o[2]); }
        if let Some(d) = inst.ext.res_dim {
            let _ = write!(n, "({})", dim_name(d));
            let r = inst.ext.ret_types.unwrap_or([5; 4]);
            n.push_str(&ret_list(r));
        }
        n
    }

    fn operands_text(&self, inst: &Instruction) -> String {
        let v: Vec<String> = inst.operands.iter().enumerate().map(|(i, o)| fmt_operand(o, operand_ty(inst, i), &self.opts, false)).collect();
        v.join(", ")
    }

    /// One declaration or instruction as text (no indentation).
    pub fn instruction_text(&self, inst: &Instruction) -> String {
        use Opcode::*;
        let o = &self.opts;
        let op0 = |u: bool| inst.operands.first().map(|x| fmt_operand(x, Ty::Untyped, o, u)).unwrap_or_default();
        match inst.op {
            DclGlobalFlags => format!("dcl_globalFlags {}", global_flags(inst.flags())).trim_end().to_string(),
            DclTemps => format!("dcl_temps {}", inst.data[0]),
            DclIndexableTemp => format!("dcl_indexableTemp x{}[{}], {}", inst.data[0], inst.data[1], inst.data[2]),
            DclConstantBuffer => format!("dcl_constantbuffer {}, {}", op0(true), if inst.flags() & 1 != 0 { "dynamicIndexed" } else { "immediateIndexed" }),
            DclSampler => format!("dcl_sampler {}, mode_{}", op0(false), match inst.flags() & 0xf { 0 => "default", 1 => "comparison", 2 => "mono", _ => "unknown" }),
            DclResource => {
                let dim = ((inst.token >> 11) & 0x1f) as u8;
                let ms = if dim == 4 || dim == 9 { format!("({})", (inst.token >> 16) & 0x7f) } else { String::new() };
                let r = [(inst.data[0] & 0xf) as u8, ((inst.data[0] >> 4) & 0xf) as u8, ((inst.data[0] >> 8) & 0xf) as u8, ((inst.data[0] >> 12) & 0xf) as u8];
                format!("dcl_resource_{}{} {} {}", dim_name(dim), ms, ret_list(r), op0(false))
            }
            DclResourceRaw => format!("dcl_resource_raw {}", op0(false)),
            DclResourceStructured => format!("dcl_resource_structured {}, {}", op0(false), inst.data[0]),
            DclUavTyped => {
                let dim = ((inst.token >> 11) & 0x1f) as u8;
                let r = [(inst.data[0] & 0xf) as u8, ((inst.data[0] >> 4) & 0xf) as u8, ((inst.data[0] >> 8) & 0xf) as u8, ((inst.data[0] >> 12) & 0xf) as u8];
                let fl = inst.token >> 16;
                let mut pre = String::new();
                if fl & 1 != 0 { pre.push_str("_glc"); }
                if fl & 2 != 0 { pre.push_str("_rov"); }
                format!("dcl_uav_typed{pre}_{} {} {}", dim_name(dim), ret_list(r), op0(false))
            }
            DclUavRaw => format!("dcl_uav_raw{} {}", if inst.token >> 16 & 1 != 0 { "_glc" } else { "" }, op0(false)),
            DclUavStructured => format!("dcl_uav_structured{} {}, {}", if inst.token >> 16 & 1 != 0 { "_glc" } else { "" }, op0(false), inst.data[0]),
            DclTgsmRaw => format!("dcl_tgsm_raw {}, {}", op0(false), inst.data[0]),
            DclTgsmStructured => format!("dcl_tgsm_structured {}, {}, {}", op0(false), inst.data[0], inst.data[1]),
            DclInput | DclOutput | DclStream => format!("{} {}", inst.op.name(), op0(false)),
            DclInputPs => format!("dcl_input_ps {} {}", interp_name((inst.token >> 11) & 0xf), op0(false)),
            DclInputSgv | DclInputSiv | DclOutputSgv | DclOutputSiv => format!("{} {}, {}", inst.op.name(), op0(false), sysvalue_long(inst.data[0])),
            DclInputPsSgv => format!("dcl_input_ps_sgv {}, {}", op0(false), sysvalue_long(inst.data[0])),
            DclInputPsSiv => format!("dcl_input_ps_siv {} {}, {}", interp_name((inst.token >> 11) & 0xf), op0(false), sysvalue_long(inst.data[0])),
            DclIndexRange => format!("dcl_indexRange {}, {}", op0(false), inst.data[0]),
            DclMaxOutputVertexCount => format!("dcl_maxout {}", inst.data[0]),
            DclThreadGroup => format!("dcl_thread_group {}, {}, {}", inst.data[0], inst.data[1], inst.data[2]),
            DclGsInputPrimitive => format!("dcl_inputprimitive {} ", match inst.flags() & 0x3f { 1 => "point".to_string(), 2 => "line".into(), 3 => "triangle".into(), 6 => "lineadj".into(), 7 => "triangleadj".into(), n @ 8..=39 => format!("patch{}_control_point", n - 7), n => format!("unknown({n})") }),
            DclGsOutputPrimitiveTopology => format!("dcl_outputtopology {} ", match inst.flags() & 0x3f { 1 => "pointlist", 3 => "linestrip", 5 => "trianglestrip", _ => "unknown" }),
            DclGsInstanceCount => format!("dcl_gsinstances {}", inst.data[0]),
            DclInputControlPointCount => format!("dcl_input_control_point_count {}", inst.flags() & 0x3f),
            DclOutputControlPointCount => format!("dcl_output_control_point_count {}", inst.flags() & 0x3f),
            DclTessDomain => format!("dcl_tessellator_domain domain_{}", match inst.flags() & 3 { 1 => "isoline", 2 => "tri", 3 => "quad", _ => "undefined" }),
            DclTessPartitioning => format!("dcl_tessellator_partitioning partitioning_{}", match inst.flags() & 7 { 1 => "integer", 2 => "pow2", 3 => "fractional_odd", 4 => "fractional_even", _ => "undefined" }),
            DclTessOutputPrimitive => format!("dcl_tessellator_output_primitive output_{}", match inst.flags() & 7 { 1 => "point", 2 => "line", 3 => "triangle_cw", 4 => "triangle_ccw", _ => "undefined" }),
            DclHsMaxTessFactor => format!("dcl_hs_max_tessfactor l({})", fmt_float(f32::from_bits(inst.data[0]))),
            DclHsForkPhaseInstanceCount => format!("dcl_hs_fork_phase_instance_count {}", inst.data[0]),
            DclHsJoinPhaseInstanceCount => format!("dcl_hs_join_phase_instance_count {}", inst.data[0]),
            DclFunctionBody => format!("dcl_function_body fb{}", inst.data[0]),
            CustomData => self.custom_text(inst),
            // d3dcompiler prints the mnemonic, a blank and the (empty) operand list
            Loop | EndLoop | Ret | Else | EndIf | Break | Continue | Default | EndSwitch | Cut | Emit | EmitThenCut | Nop | HsDecls | HsControlPointPhase | HsForkPhase | HsJoinPhase => format!("{} ", inst.op.name()),
            Unknown(n) => format!("// unknown opcode {n} {}", self.operands_text(inst)),
            _ => {
                let m = self.mnemonic(inst);
                let ops = self.operands_text(inst);
                if ops.is_empty() { m } else { format!("{m} {ops}") }
            }
        }
    }

    fn custom_text(&self, inst: &Instruction) -> String {
        match inst.custom_class {
            3 => {
                let o = &self.opts;
                let rows: Vec<String> = inst.data.chunks(4).filter(|c| c.len() == 4).map(|c| {
                    let v: Vec<String> = c.iter().map(|&b| fmt_imm(b, Ty::Untyped, o)).collect();
                    format!("{{ {}}}", v.join(", "))
                }).collect();
                let pad = " ".repeat(30);
                let mut s = String::from("dcl_immediateConstantBuffer { ");
                for (i, r) in rows.iter().enumerate() {
                    if i > 0 { s.push_str(&format!(",\n{pad}")); }
                    s.push_str(r);
                }
                s.push_str(" }");
                s
            }
            0 => "// comment".to_string(),
            1 => "// debug info".to_string(),
            c => format!("// custom data class {c}"),
        }
    }

    /// Body listing (declarations and instructions) with d3dcompiler indentation.
    pub fn body_text(&self) -> String {
        use Opcode::*;
        let mut out = String::new();
        let mut indent = 0usize;
        // switch bookkeeping: true = currently inside a case body
        let mut in_case: Vec<bool> = Vec::new();
        for inst in &self.shader.instructions {
            let mut pre = indent;
            match inst.op {
                EndIf | EndLoop => { indent = indent.saturating_sub(1); pre = indent; }
                Else => { pre = indent.saturating_sub(1); }
                EndSwitch => {
                    if in_case.pop() == Some(true) { indent = indent.saturating_sub(1); }
                    indent = indent.saturating_sub(1);
                    pre = indent;
                }
                Case | Default => {
                    if let Some(c) = in_case.last_mut() {
                        if *c { indent = indent.saturating_sub(1); }
                        *c = true;
                    }
                    pre = indent;
                }
                _ => {}
            }
            let text = self.instruction_text(inst);
            for (li, line) in text.split('\n').enumerate() {
                if li == 0 { let _ = writeln!(out, "{}{}", "  ".repeat(pre), line); } else { let _ = writeln!(out, "{line}"); }
            }
            match inst.op {
                If | Loop => indent += 1,
                Switch => { indent += 1; in_case.push(false); }
                Case | Default => indent += 1,
                _ => {}
            }
        }
        out
    }
}

fn mask_str(m: u8) -> String { COMP.iter().enumerate().map(|(c, ch)| if m & (1 << c) != 0 { *ch } else { ' ' }).collect() }

fn sig_text(title: &str, sig: Option<&Signature>, is_output: bool, out: &mut String) {
    let _ = writeln!(out, "// {title}:");
    let _ = writeln!(out, "//");
    let _ = writeln!(out, "// Name                 Index   Mask Register SysValue  Format   Used");
    let _ = writeln!(out, "// -------------------- ----- ------ -------- -------- ------- ------");
    match sig {
        Some(s) if !s.elements.is_empty() => {
            for e in &s.elements { let _ = writeln!(out, "{}", sig_row(e, is_output)); }
        }
        _ => { let _ = writeln!(out, "// no {}", if is_output { "Output" } else { "Input" }); }
    }
}

fn sig_row(e: &SigElement, is_output: bool) -> String {
    // output signatures store the components that are never written; the listing shows what is used
    let used = if is_output { e.mask & !e.rw_mask } else { e.mask & e.rw_mask };
    format!("// {:<20} {:>5}   {} {:>8} {:>8} {:>7}   {}", e.name, e.semantic_index, mask_str(e.mask), e.register, e.sysvalue_name(), e.format_name(), mask_str(used))
}

fn rdef_text(r: &Rdef, out: &mut String) {
    if !r.cbuffers.is_empty() {
        let _ = writeln!(out, "// Buffer Definitions: ");
        let _ = writeln!(out, "//");
        for cb in &r.cbuffers {
            let _ = writeln!(out, "// {} {}", if cb.kind == 1 { "tbuffer" } else { "cbuffer" }, cb.name);
            let _ = writeln!(out, "// {{");
            let _ = writeln!(out, "//");
            for v in &cb.vars {
                let ty = v.ty.hlsl_name();
                let arr = if v.ty.elements > 0 { format!("[{}]", v.ty.elements) } else { String::new() };
                let _ = writeln!(out, "//   {} {}{};{} // Offset: {:>4} Size: {:>5}", ty, v.name, arr, " ".repeat(0), v.offset, v.size);
            }
            let _ = writeln!(out, "//");
            let _ = writeln!(out, "// }}");
            let _ = writeln!(out, "//");
        }
        let _ = writeln!(out, "//");
    }
    if !r.bindings.is_empty() {
        let _ = writeln!(out, "// Resource Bindings:");
        let _ = writeln!(out, "//");
        let _ = writeln!(out, "// Name                                 Type  Format         Dim Slot Elements");
        let _ = writeln!(out, "// ------------------------------ ---------- ------- ----------- ---- --------");
        for b in &r.bindings {
            let kind = match b.kind { 0 => "cbuffer", 1 => "tbuffer", 2 => "texture", 3 => "sampler", 4 => "UAV", 5 => "structured", 6 => "UAV", 7 => "structured", 8 => "UAV", 9 => "UAV", 10 => "UAV", _ => "?" };
            let fmt = if b.kind == 2 || b.kind >= 4 { match b.return_type { 1 => "unorm", 2 => "snorm", 3 => "sint", 4 => "uint", 5 => "float", 6 => "mixed", 7 => "double", _ => "NA" } } else { "NA" };
            let dim = match b.dimension { 0 => "NA", 1 => "buf", 2 => "1d", 3 => "1darray", 4 => "2d", 5 => "2darray", 6 => "2dMS", 7 => "2dMSarray", 8 => "3d", 9 => "cube", 10 => "cubearray", _ => "NA" };
            let _ = writeln!(out, "// {:<30} {:>10} {:>7} {:>11} {:>4} {:>8}", b.name, kind, fmt, dim, b.bind_point, b.bind_count);
        }
        let _ = writeln!(out, "//");
    }
}

/// Full d3dcompiler-style listing of a container.
pub fn disassemble_container(c: &Container, opts: DisasmOptions) -> Result<String> {
    let shader = Shader::from_container(c)?;
    let mut out = String::new();
    out.push_str("//\n// Generated by Microsoft (R) D3D Shader Disassembler\n//\n");
    if let Some(r) = c.rdef() { rdef_text(&r, &mut out); }
    out.push_str("//\n");
    let isg = c.input_signature();
    let osg = c.output_signature();
    sig_text("Input signature", isg.as_ref(), false, &mut out);
    let in_none = isg.as_ref().map_or(true, |s| s.elements.is_empty());
    if !in_none { out.push_str("//\n"); }
    out.push_str("//\n");
    sig_text("Output signature", osg.as_ref(), true, &mut out);
    let out_none = osg.as_ref().map_or(true, |s| s.elements.is_empty());
    if !out_none { out.push_str("//\n"); }
    let d = Disassembler { shader: &shader, opts };
    let _ = writeln!(out, "{}", shader.version_string());
    out.push_str(&d.body_text());
    let _ = writeln!(out, "// Approximately {} instruction slots used", c.stat_instruction_count().unwrap_or(0));
    Ok(out)
}

pub fn disassemble(bytes: &[u8]) -> Result<String> { disassemble_container(&Container::parse(bytes)?, DisasmOptions::default()) }
pub fn disassemble_hex(bytes: &[u8]) -> Result<String> { disassemble_container(&Container::parse(bytes)?, DisasmOptions { hex_literals: true }) }

/// Listing of a bare program (no signatures): version line + body.
pub fn disassemble_program(words: &[u32]) -> Result<String> {
    let shader = decode_program(words)?;
    let d = Disassembler { shader: &shader, opts: DisasmOptions::default() };
    Ok(format!("{}\n{}", shader.version_string(), d.body_text()))
}





